typedef unsigned long long ull;

static ull pow10u(int e) {
    ull r = 1;
    while (e--) r *= 10ULL;
    return r;
}

static int digits_ull(ull x) {
    int d = 0;
    do {
        d++;
        x /= 10ULL;
    } while (x);
    return d;
}

/* Number of digits in Champernowne constant before integer n starts (1-based integers). */
static ull pos_before(ull n) {
    if (n <= 1) return 0;
    ull ans = 0;
    int d = digits_ull(n - 1);
    ull p = 1;
    for (int k = 1; k < d; k++) {
        ans += 9ULL * p * (ull)k;
        p *= 10ULL;
    }
    ans += (n - p) * (ull)d;
    return ans;
}

static void to_str_ull(ull x, char *s) {
    sprintf(s, "%llu", x);
}

static int starts_with(const char *a, const char *b) {
    while (*b) {
        if (*a != *b) return 0;
        a++; b++;
    }
    return 1;
}

static ull best_ans;
static char target[64];
static int L;

/* Check candidate starting at integer n, where pattern begins at offset off inside n's decimal representation. */
static void check_candidate(ull n, int off) {
    if (n == 0) return;

    char buf[256] = {0};
    char tmp[32];
    int len = 0;

    ull cur = n;
    while (len < L + 25) {
        to_str_ull(cur, tmp);
        int tl = (int)strlen(tmp);
        if (len + tl >= (int)sizeof(buf) - 1) break;
        memcpy(buf + len, tmp, tl);
        len += tl;
        buf[len] = 0;
        cur++;
    }

    if (off < 0 || off >= len) return;
    if (off + L > len) return;
    if (strncmp(buf + off, target, L) != 0) return;

    ull pos = pos_before(n) + (ull)off + 1ULL; /* 1-based position */
    if (pos < best_ans) best_ans = pos;
}

int main(void) {
    if (scanf("%63s", target) != 1) return 0;
    L = (int)strlen(target);

    best_ans = ~0ULL;

    /* Case 1: pattern starts at beginning of some integer whose decimal string is target itself. */
    if (!(L > 1 && target[0] == '0')) {
        ull n = strtoull(target, NULL, 10);
        if (n >= 1) {
            ull pos = pos_before(n) + 1ULL;
            if (pos < best_ans) best_ans = pos;
        }
    }

    /* Enumerate all ways target can overlap consecutive integers. */
    for (int lenN = 1; lenN <= L; lenN++) {
        for (int off = 0; off < lenN; off++) {
            /* Need suffix of n of length lenN-off to equal target prefix of same length. */
            int suf = lenN - off;
            if (suf > L) continue;

            if (off == 0) {
                /* n is fully determined by first lenN digits of target */
                if (lenN > 1 && target[0] == '0') continue;
                char part[32];
                memcpy(part, target, lenN);
                part[lenN] = 0;
                ull n = strtoull(part, NULL, 10);
                if (n >= 1) check_candidate(n, off);
            } else {
                /* Need to reconstruct n from suffix; prefix digits of n are unknown. Try all possibilities. */
                char sufstr[32];
                memcpy(sufstr, target, suf);
                sufstr[suf] = 0;
                ull suffix = strtoull(sufstr, NULL, 10);
                ull base = pow10u(suf);
                ull prefCount = pow10u(off);

                for (ull pref = 0; pref < prefCount; pref++) {
                    if (off > 1 && pref < pow10u(off - 1)) continue; /* must keep total length lenN */
                    ull n = pref * base + suffix;
                    if (digits_ull(n) != lenN) continue;
                    if (n >= 1) check_candidate(n, off);
                }
            }
        }
    }

    printf("%llu\n", best_ans);
    return 0;
}

