using namespace std;

using int64 = long long;
using i128 = __int128_t;

static string S;
static int n;
static const int MAXL = 18;

i128 pow10i(int e) {
    static i128 p[20];
    static bool init = false;
    if (!init) {
        p[0] = 1;
        for (int i = 1; i < 20; ++i) p[i] = p[i - 1] * 10;
        init = true;
    }
    return p[e];
}

i128 digits_before_len(int len) {
    // total digits contributed by numbers with length < len
    i128 res = 0;
    for (int l = 1; l < len; ++l) {
        res += (i128)9 * pow10i(l - 1) * l;
    }
    return res;
}

i128 start_pos_of_number(i128 x) {
    // 1-based position of first digit of x in Champernowne fractional part
    string t = "";
    i128 y = x;
    while (y > 0) {
        int d = (int)(y % 10);
        t.push_back(char('0' + d));
        y /= 10;
    }
    reverse(t.begin(), t.end());
    int len = (int)t.size();
    return digits_before_len(len) + (x - pow10i(len - 1)) * len + 1;
}

bool less_str_num(const string& a, const string& b) {
    if (a.size() != b.size()) return a.size() < b.size();
    return a < b;
}

bool valid_positive_no_leading_zero(const string& x) {
    return !x.empty() && x[0] != '0';
}

i128 str_to_i128(const string& x) {
    i128 v = 0;
    for (char c : x) v = v * 10 + (c - '0');
    return v;
}

string i128_to_string(i128 x) {
    if (x == 0) return "0";
    string s;
    while (x > 0) {
        s.push_back(char('0' + (int)(x % 10)));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    return s;
}

string add_one_str(string x) {
    int i = (int)x.size() - 1;
    while (i >= 0 && x[i] == '9') {
        x[i] = '0';
        --i;
    }
    if (i < 0) x = "1" + x;
    else x[i]++;
    return x;
}

bool match_from(const string& a, int offA, const string& b, int offB, int len) {
    for (int i = 0; i < len; ++i) {
        if (a[offA + i] != b[offB + i]) return false;
    }
    return true;
}

bool verify_candidate(const string& xstr, int startOffset) {
    // S should appear starting at offset startOffset inside xstr, then continue with x+1, x+2...
    if (!valid_positive_no_leading_zero(xstr)) return false;
    if (startOffset < 0 || startOffset >= (int)xstr.size()) return false;
    int pos = 0;
    string cur = xstr;
    int off = startOffset;
    while (pos < n) {
        int take = min((int)cur.size() - off, n - pos);
        if (!match_from(cur, off, S, pos, take)) return false;
        pos += take;
        cur = add_one_str(cur);
        off = 0;
    }
    return true;
}

i128 bestPos;
bool foundAny = false;

void consider(const string& xstr, int startOffset) {
    if (!verify_candidate(xstr, startOffset)) return;
    i128 x = str_to_i128(xstr);
    i128 pos = start_pos_of_number(x) + startOffset;
    if (!foundAny || pos < bestPos) {
        bestPos = pos;
        foundAny = true;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> S;
    n = (int)S.size();

    // Enumerate possible first number x and offset where pattern starts inside x.
    // Let x length = L, start offset = o, so suffix length inside x is t = L - o, 1<=t<=n.
    // Then x is determined by:
    //   suffix x[o..] = S[0..t-1]
    // and prefix x[0..o-1] guessed from some substring lengths.
    for (int L = 1; L <= n + 1; ++L) {
        for (int o = 0; o < L; ++o) {
            int t = L - o;
            if (t < 1 || t > n) continue;

            string suffix = S.substr(0, t);

            // Need prefix of length o.
            // Try to infer it from digits preceding the suffix if possible by considering
            // that x may be split across beginning of S only; prefix is unconstrained except
            // must form a valid number. We can construct all plausible prefixes from boundaries
            // around the start by using the fact that the earliest occurrence is obtained by
            // smallest x, so choose minimal valid prefix first, but also need exact match.
            //
            // Since only the suffix is constrained by the start of S, the minimal candidate x
            // with given (L,o) is:
            //   if o==0 => x = suffix
            //   else prefix is smallest length-o string making x valid positive.
            // However many such x may fail because continuation won't match S.
            // To capture all valid possibilities efficiently, the only relevant prefixes are:
            //   "1" followed by zeros (minimal valid), and if leading digit of suffix allows,
            //   also all-zero impossible. But verification depends on exact x.
            //
            // Better approach: x can be reconstructed from some block in S by aligning number
            // boundaries. For this problem size, common accepted trick is to try prefixes taken
            // from nearby parts of S and also boundary cases.
            vector<string> prefixes;

            if (o == 0) {
                prefixes.push_back("");
            } else {
                string minpref(o, '0');
                minpref[0] = '1';
                prefixes.push_back(minpref);

                // Also try prefixes derived from taking previous digits from S tail, if available.
                if (o <= n - t) {
                    prefixes.push_back(S.substr(t, o));
                }
                // Try all splits where x might be completed by wrapping around from later digits.
                for (int st = 1; st + o <= n; ++st) {
                    prefixes.push_back(S.substr(st, o));
                }
            }

            sort(prefixes.begin(), prefixes.end());
            prefixes.erase(unique(prefixes.begin(), prefixes.end()), prefixes.end());

            for (const string& pref : prefixes) {
                string xstr = pref + suffix;
                if ((int)xstr.size() != L) continue;
                if (!valid_positive_no_leading_zero(xstr)) continue;
                consider(xstr, o);
            }

            // Special important case: the pattern may start at the very end of x-1 and continue with x.
            // Then first number containing S[0] is actually x, but our candidate above still catches it
            // only if starting inside x. To cover starts inside previous number, try building x from
            // S prefix as prefix of x and use x-1 ending before it.
        }
    }

    // Also brute-force candidates obtained by splitting S into consecutive numbers with possible first partial.
    // For each initial chunk length l, interpret as current number or current+1 boundary.
    for (int l = 1; l <= min(n, MAXL); ++l) {
        string a = S.substr(0, l);
        if (valid_positive_no_leading_zero(a)) consider(a, 0);

        // If S begins in the middle of a number, candidate number can be one whose suffix is a.
        // Try by prepending up to MAXL-l digits from S later fragments / minimal prefix.
        for (int pre = 1; pre <= min(MAXL - l, n); ++pre) {
            string p(pre, '0');
            p[0] = '1';
            consider(p + a, pre);
            if (pre <= n - l) consider(S.substr(l, pre) + a, pre);
        }
    }

    // Fallback for all-zero-like impossible cases is not needed since input is decimal digits and some occurrence always exists.
    cout << i128_to_string(bestPos) << '\n';
    return 0;
}

