        Scanner sc = new Scanner(System.in);
        String sequence = sc.nextLine().trim();
        sc.close();

        StringBuilder sb = new StringBuilder();
        int n = 1;
        while (true) {
            sb.append(n);
            // Check only the tail where a new match could appear
            int len = sb.length();
            int startCheck = Math.max(0, len - sequence.length() - ("" + n).length());
            String tail = sb.substring(startCheck);
            int idx = tail.indexOf(sequence);
            if (idx != -1) {
                System.out.println(startCheck + idx);
                return;
            }
            n++;
        }
    }
}

