        // Try each possible starting digit-length d
        for (int d = 1; d <= 15; d++) {
            BigInteger start = BigInteger.TEN.pow(d-1);
            if (d == 1) start = BigInteger.ONE;
            // For each offset within the first number (0 to d-1)
            for (int off = 0; off < d; off++) {
                // The pattern starts at position 'off' within number n
                // We need to find n such that digits of n starting at off, then n+1, n+2... match pattern
                // Build what n's suffix should be (first d-off chars of pattern)
                int take = Math.min(d - off, L);
                String prefix = pattern.substring(0, take);
                // n must end with 'prefix' at position off
                // So digits of n: positions 0..off-1 are free, positions off..d-1 = prefix
                // n is a d-digit number
                // Find smallest such n >= 10^(d-1)
                // n's last (d-off) digits are determined by prefix (if take == d-off)
                if (take < d - off) {
                    // pattern is shorter than remaining digits in n, handle carefully
                }
                // Try: set the suffix of n and iterate
                // Actually let me just try all n in range but that's too slow
                // Better: fix the suffix, compute n
                BigInteger candidate = tryOffset(d, off, start);
                if (candidate != null) {
                    if (best == null || candidate.compareTo(best) < 0) best = candidate;
                }
            }
            // Once numbers are large enough that a single number contains pattern, we can stop
            if (d >= L) break;
        }
        return best;
    }

import java.io.*;
import java.util.*;

public class Main {
    static final long INF = Long.MAX_VALUE / 4;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) return;
        s = s.trim();
        System.out.println(solve(s));
    }

    static long solve(String s) {
        long ans = directInsideOneNumber(s);

        int n = s.length();

        // Try all ways the pattern can start inside some number and continue
        // through consecutive numbers.
        for (int len = 1; len <= n + 1; len++) {
            for (int start = 0; start < n; start++) {
                int takeFirst = Math.min(len, n - start);
                String firstPart = s.substring(start, start + takeFirst);

                // Candidate starting number x whose suffix matches firstPart
                List<Long> candidates = buildCandidates(firstPart, len);

                for (long x : candidates) {
                    if (x <= 0) continue;
                    if (String.valueOf(x).length() != len) continue;

                    int offset = len - firstPart.length(); // digits before s[start] inside x
                    if (matchesFrom(s, start, x, offset)) {
                        long pos = digitsBefore(x) + offset - start + 1; // 1-based
                        if (pos < ans) ans = pos;
                    }
                }
            }
        }

        return ans;
    }

    // Check if s can be read starting at digit 'offset' inside decimal representation of x,
    // then continuing through x, x+1, x+2, ...
    static boolean matchesFrom(String s, int startInS, long x, int offset) {
        int idx = startInS;
        long cur = x;
        int off = offset;
        while (idx < s.length()) {
            String t = Long.toString(cur);
            for (int i = off; i < t.length() && idx < s.length(); i++) {
                if (s.charAt(idx) != t.charAt(i)) return false;
                idx++;
            }
            cur++;
            off = 0;
        }
        return true;
    }

    // Build all len-digit numbers whose suffix equals suffixPart.
    static List<Long> buildCandidates(String suffixPart, int len) {
        List<Long> res = new ArrayList<>();
        int k = suffixPart.length();
        if (k > len) return res;

        if (k == len) {
            if (suffixPart.charAt(0) != '0') {
                tryAdd(res, Long.parseLong(suffixPart));
            }
            return dedup(res);
        }

        int prefixLen = len - k;

        // Prefix can be:
        // 1) all 9s, useful near boundaries like 99|100
        // 2) all 0s except first digit 1..9
        // 3) if prefixLen small, brute all prefixes
        if (prefixLen <= 6) {
            long start = pow10(prefixLen - 1);
            long end = pow10(prefixLen) - 1;
            for (long p = start; p <= end; p++) {
                String cand = Long.toString(p) + suffixPart;
                if (cand.charAt(0) != '0') tryAdd(res, Long.parseLong(cand));
            }
        } else {
            StringBuilder sb9 = new StringBuilder();
            for (int i = 0; i < prefixLen; i++) sb9.append('9');
            tryAdd(res, Long.parseLong(sb9.toString() + suffixPart));

            for (char c = '1'; c <= '9'; c++) {
                StringBuilder sb = new StringBuilder();
                sb.append(c);
                for (int i = 1; i < prefixLen; i++) sb.append('0');
                sb.append(suffixPart);
                tryAdd(res, Long.parseLong(sb.toString()));
            }
        }

        return dedup(res);
    }

    static List<Long> dedup(List<Long> list) {
        Collections.sort(list);
        List<Long> res = new ArrayList<>();
        Long prev = null;
        for (Long v : list) {
            if (prev == null || !prev.equals(v)) res.add(v);
            prev = v;
        }
        return res;
    }

    static void tryAdd(List<Long> list, long v) {
        if (v > 0) list.add(v);
    }

    // Find occurrences wholly inside one number.
    static long directInsideOneNumber(String s) {
        int n = s.length();
        long ans = INF;

        // For each possible total length of the containing number
        for (int len = n; len <= n + 1; len++) {
            int extra = len - n;
            for (int off = 0; off <= extra; off++) {
                int prefLen = off;
                int suffLen = extra - off;

                if (prefLen + suffLen == 0) {
                    if (s.charAt(0) != '0') {
                        long x = Long.parseLong(s);
                        long pos = digitsBefore(x) + 1;
                        if (pos < ans) ans = pos;
                    }
                } else {
                    // Try small set of plausible prefixes/suffixes
                    List<String> prefs = generateSides(prefLen, true);
                    List<String> suffs = generateSides(suffLen, false);
                    for (String p : prefs) {
                        for (String q : suffs) {
                            String t = p + s + q;
                            if (t.length() != len) continue;
                            if (t.charAt(0) == '0') continue;
                            long x = Long.parseLong(t);
                            long pos = digitsBefore(x) + prefLen + 1;
                            if (pos < ans) ans = pos;
                        }
                    }
                }
            }
        }

        return ans;
    }

    static List<String> generateSides(int len, boolean prefix) {
        List<String> res = new ArrayList<>();
        if (len == 0) {
            res.add("");
            return res;
        }
        if (len <= 3) {
            int from = 0;
            int to = (int) pow10(len) - 1;
            for (int i = from; i <= to; i++) {
                String x = String.format("%0" + len + "d", i);
                res.add(x);
            }
        } else {
            StringBuilder z = new StringBuilder();
            for (int i = 0; i < len; i++) z.append('0');
            res.add(z.toString());

            StringBuilder n = new StringBuilder();
            for (int i = 0; i < len; i++) n.append('9');
            res.add(n.toString());

            StringBuilder one = new StringBuilder();
            one.append('1');
            for (int i = 1; i < len; i++) one.append('0');
            res.add(one.toString());
        }
        return res;
    }

    // Number of digits before integer x in Champernowne sequence, plus 1 for 1-based position.
    // Example: x=1 -> 0 digits before it.
    static long digitsBefore(long x) {
        long ans = 0;
        long base = 1;
        int len = 1;
        while (base * 10L <= x) {
            ans += 9L * base * len;
            base *= 10L;
            len++;
        }
        ans += (x - base) * len;
        return ans;
    }

    static long pow10(int e) {
        long r = 1;
        for (int i = 0; i < e; i++) r *= 10L;
        return r;
    }
}
